  const [currentActivityIndex, setCurrentActivityIndex] = useState(0);
  const [copied, setCopied] = useState(false);

  // Chat States
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! মিস্টার বাংলা স্টুডিওতে আপনাকে স্বাগতম। আমি আপনার ডিজিটাল অ্যাসিস্ট্যান্ট। আমাদের এডিটিং সার্ভিস নিয়ে কোনো প্রশ্ন আছে? প্যাকেজ সম্পর্কে জানতে আমাকে জিজ্ঞেস করতে পারেন।' }
  ]);
